import {showPass} from './event-pass.js';
import {currentApplication} from './catalog-state.js';
import {connectFirebase} from './firebase-client.js';
import {linkedEvent} from './event-link.js';
import {openEventDetail} from './event-detail.js';
import {rememberEvent} from './enrollment-intent.js';
let generation=0,stop=()=>{},ownedModal=false;
async function page(){const version=++generation;stop();const modal=document.querySelector('#modal');if(ownedModal){modal.close();ownedModal=false}const id=linkedEvent(location.hash);if(!id)return;const main=document.querySelector('#app');main.replaceChildren();const root=document.createElement('section');root.className='form';const title=document.createElement('h2');title.textContent='รายละเอียดกิจกรรม';const status=document.createElement('p');status.setAttribute('role','status');status.textContent='กำลังโหลดกิจกรรม…';const reopen=document.createElement('button');reopen.textContent='เปิดรายละเอียดกิจกรรม';reopen.hidden=true;const back=document.createElement('a');back.href='#live-events';back.textContent='ดูกิจกรรมทั้งหมด →';root.append(title,status,reopen,back);main.append(root);
 try{const client=await connectFirebase();if(version!==generation)return;let disposeAccount=()=>{},disposeEvents=()=>{},disposeApps=()=>{},scope=0;stop=()=>{scope++;disposeAccount();disposeEvents();disposeApps()};disposeAccount=client.observeAccount(user=>{const account=++scope;disposeEvents();disposeApps();if(ownedModal){modal.close();ownedModal=false}let events=null,apps=user?null:[],cached=true,opened=false;const current=()=>version===generation&&scope===account&&root.isConnected;
 const draw=()=>{if(!current()||events===null||apps===null)return;const event=events.find(e=>e.id===id&&e.published!==false&&e.deleted!==true&&!e.purging);if(!event){if(cached){status.textContent='กำลังเชื่อมต่อเพื่อโหลดข้อมูลล่าสุด…';return}if(ownedModal){modal.close();ownedModal=false}reopen.hidden=true;status.textContent='กิจกรรมนี้ไม่เปิดให้บริการ อาจยังไม่เผยแพร่หรือถูกยกเลิก กรุณาเลือกกิจกรรมอื่น';return}title.textContent=event.name;status.textContent=cached?'กำลังตรวจสอบข้อมูลล่าสุด…':'เลือกดูรายละเอียด แล้วสมัครเข้าร่วมได้จากปุ่มด้านล่าง';reopen.hidden=false;
 const existing=apps.find(a=>a.eventId===id&&['pending','approved'].includes(a.status));const show=()=>{if(!current())return;ownedModal=true;openEventDetail(event,()=>{ownedModal=false;if(!current())return;if(existing){if(existing.status==='approved'){ownedModal=true;showPass(currentApplication(existing,event))}else location.hash='#live-mine';return}rememberEvent(id);location.hash=user?'#live-events':'#real-account'},{actionLabel:existing?(existing.status==='approved'?'เปิดบัตรเข้างาน':'ดูสถานะใบสมัคร'):user?'สมัครเข้าร่วมกิจกรรม':'เข้าสู่ระบบเพื่อสมัคร',allowAction:!!existing})};reopen.onclick=show;if(!opened&&!cached){opened=true;show()}};
 disposeEvents=client.watchEvents((data,metadata)=>{events=data;cached=metadata.fromCache;draw()},()=>{if(current())status.textContent='โหลดกิจกรรมไม่ได้ กรุณาตรวจสอบอินเทอร์เน็ตแล้วเปิดลิงก์อีกครั้ง'});if(user)disposeApps=client.watchMyApplications(data=>{apps=data;draw()},()=>{if(current())status.textContent='ตรวจสอบใบสมัครเดิมไม่ได้ กรุณาเปิดลิงก์อีกครั้งเพื่อป้องกันสมัครซ้ำ'});
 });}catch{if(version===generation)status.textContent='เชื่อมต่อไม่ได้ กรุณาตรวจสอบอินเทอร์เน็ตแล้วลองใหม่'}
}
window.addEventListener('hashchange',page);page();
